// Writes a small page for every event at /<event>/index.html so WhatsApp (and other apps) show
// the couple's names and photo when the link is shared. The page itself loads the shared RSVP form.
// Only files this job wrote (marked kai-preview) are ever replaced; custom pages like /maya-yotam are left alone.
import fs from 'node:fs';
import path from 'node:path';

const HUB = 'https://script.google.com/macros/s/AKfycbwu6hLPWCdnjcX8NVWjCHjQHNrP5Tjj-lx76JgHN7OEfZYDx30dP0FAJVVAbL3s06WQ/exec';
const SITE = 'https://weddings.kaiwedd.com/';
const MARK = '<!-- kai-preview -->';

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
function when(ev) {
  if (ev.dates) return ev.dates.replace(/\s+/g, ' ');
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(ev.date || '');
  return m ? `${Number(m[3])}.${Number(m[2])}.${m[1]}` : '';
}

const res = await fetch(HUB, { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify({ action: 'previews' }) });
const data = await res.json();
if (!data.ok) throw new Error('Hub said: ' + JSON.stringify(data));

for (const ev of data.events) {
  if (!/^[a-z0-9-]+$/.test(ev.slug)) continue;
  const file = path.join(ev.slug, 'index.html');
  if (fs.existsSync(file) && !fs.readFileSync(file, 'utf8').includes(MARK)) { console.log('custom page, skipped:', ev.slug); continue; }
  const title = `${ev.couple} – We’re getting married!`;
  const desc = [ev.place, when(ev), 'You’re invited'].filter(Boolean).join(' · ');
  const html = `<!doctype html>
${MARK}
<html lang="${ev.lang === 'en' ? 'en' : 'he'}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>${esc(title)}</title>
<meta name="description" content="${esc(desc)}">
<meta property="og:type" content="website">
<meta property="og:url" content="${esc(SITE + ev.slug)}">
<meta property="og:title" content="${esc(title)}">
<meta property="og:description" content="${esc(desc)}">
${ev.image ? `<meta property="og:image" content="${esc(ev.image)}">\n<meta name="twitter:card" content="summary_large_image">\n` : ''}</head>
<body style="margin:0;background:#E9E3D8">
<!-- Generated by .github/scripts/previews.mjs. The form itself is the shared /app/rsvp.html. -->
<script>
fetch('/app/rsvp.html', { cache: 'no-store' }).then(function (r) { return r.text(); }).then(function (html) { document.open(); document.write(html); document.close(); });
</script>
</body>
</html>
`;
  const old = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
  if (old !== html) { fs.mkdirSync(ev.slug, { recursive: true }); fs.writeFileSync(file, html); console.log('updated:', ev.slug); }
}
